<script setup>
import { Head, Link, useForm, usePage } from '@inertiajs/vue3';
import AdminLayout from '../../../Layouts/AdminLayout.vue';
import AdminPageHeader from '../../../Components/Admin/AdminPageHeader.vue';
import AdminCard from '../../../Components/Admin/AdminCard.vue';
import AdminButton from '../../../Components/Admin/AdminButton.vue';
import AdminPagination from '../../../Components/Admin/AdminPagination.vue';
import StatusBadge from '../../../Components/Admin/StatusBadge.vue';
import EmptyState from '../../../Components/Admin/EmptyState.vue';

const props = defineProps({ leads: Object, filters: Object, statusOptions: Array, projectTypeOptions: Array });
const page = usePage();
const form = useForm({ search: props.filters.search || '', status: props.filters.status || '', project_type: props.filters.project_type || '' });
const filter = () => form.get(page.url.split('?')[0], { preserveState: true, replace: true });
const reset = () => { form.search = ''; form.status = ''; form.project_type = ''; filter(); };
const date = value => new Intl.DateTimeFormat('id-ID', { dateStyle: 'medium' }).format(new Date(value));
</script>
<template>
    <Head title="Leads | Admin SCH Management"><meta name="robots" content="noindex, nofollow"/></Head>
    <AdminLayout><AdminPageHeader title="Leads" description="Tinjau permintaan masuk, perbarui status, dan simpan catatan internal tanpa mengubah pesan asli."/><AdminCard><form class="grid gap-3 border-b border-sch-border p-4 sm:grid-cols-2 xl:grid-cols-[1fr_12rem_15rem_auto]" role="search" @submit.prevent="filter"><label class="text-xs font-semibold text-sch-muted">Pencarian<input v-model="form.search" type="search" placeholder="Nama, email, perusahaan, WhatsApp..." class="mt-1.5 min-h-11 w-full rounded-xl border border-sch-border px-3.5 text-sm"/></label><label class="text-xs font-semibold text-sch-muted">Status<select v-model="form.status" class="mt-1.5 min-h-11 w-full rounded-xl border border-sch-border px-3 text-sm"><option value="">Semua</option><option v-for="option in statusOptions" :key="option.value" :value="option.value">{{ option.label }}</option></select></label><label class="text-xs font-semibold text-sch-muted">Jenis project<select v-model="form.project_type" class="mt-1.5 min-h-11 w-full rounded-xl border border-sch-border px-3 text-sm"><option value="">Semua</option><option v-for="option in projectTypeOptions" :key="option" :value="option">{{ option }}</option></select></label><div class="flex gap-2 self-end"><AdminButton type="submit">Terapkan</AdminButton><AdminButton type="button" variant="secondary" @click="reset">Reset</AdminButton></div></form><EmptyState v-if="!leads.data.length" title="Belum ada lead." description="Lead asli akan muncul setelah sistem kontak publik dibangun pada fase yang sesuai."/><template v-else><div class="hidden overflow-x-auto md:block"><table class="w-full min-w-[780px] text-left text-sm"><thead class="border-b border-sch-border bg-slate-50 text-xs uppercase tracking-wide text-sch-muted"><tr><th class="px-5 py-3.5">Nama</th><th class="px-5 py-3.5">Kontak</th><th class="px-5 py-3.5">Project</th><th class="px-5 py-3.5">Budget</th><th class="px-5 py-3.5">Tanggal</th><th class="px-5 py-3.5">Status</th></tr></thead><tbody class="divide-y divide-sch-border"><tr v-for="lead in leads.data" :key="lead.id" class="hover:bg-slate-50"><td class="px-5 py-4"><Link :href="lead.show_url" class="font-semibold text-sch-navy hover:text-sch-blue hover:underline">{{ lead.name }}</Link><p class="mt-1 text-xs text-sch-muted">{{ lead.company || 'Tanpa perusahaan' }}</p></td><td class="px-5 py-4 text-sch-muted"><span class="block">{{ lead.email }}</span><span class="block text-xs">{{ lead.whatsapp }}</span></td><td class="px-5 py-4 text-sch-muted">{{ lead.project_type }}</td><td class="px-5 py-4 text-sch-muted">{{ lead.budget_range || '—' }}</td><td class="px-5 py-4 text-sch-muted">{{ date(lead.created_at) }}</td><td class="px-5 py-4"><StatusBadge :value="lead.status"/></td></tr></tbody></table></div><div class="divide-y divide-sch-border md:hidden"><Link v-for="lead in leads.data" :key="lead.id" :href="lead.show_url" class="block p-5 hover:bg-slate-50"><div class="flex items-start justify-between gap-3"><div><h2 class="font-semibold text-sch-navy">{{ lead.name }}</h2><p class="mt-1 text-sm text-sch-muted">{{ lead.company || lead.email }}</p></div><StatusBadge :value="lead.status"/></div><div class="mt-4 flex justify-between gap-4 text-xs text-sch-muted"><span>{{ lead.project_type }}</span><span>{{ date(lead.created_at) }}</span></div></Link></div><AdminPagination :links="leads.links" :from="leads.from" :to="leads.to" :total="leads.total"/></template></AdminCard></AdminLayout>
</template>
